{% set co = frappe.db.get_value('Company', doc.company, ['company_name','phone_no','email','tax_id','company_logo','default_currency'], as_dict=1) or {} %}
{% set co_name  = co.get('company_name') or doc.company or '' %}
{% set co_phone = co.get('phone_no') or '' %}
{% set co_email = co.get('email') or '' %}
{% set co_tax   = co.get('tax_id') or '' %}
{% set co_currency = co.get('default_currency') or frappe.defaults.get_global_default('currency') %}
{% set co_logo  = '/assets/jms/images/oasis-cienteirs-logo.png' %}
{% set addr_doc = {} %}
{% if doc.company %}
  {% set dl = frappe.db.sql("SELECT parent FROM `tabDynamic Link` WHERE link_doctype='Company' AND link_name=%s AND parenttype='Address' LIMIT 1", doc.company) %}
  {% if dl %}
    {% set addr_doc = frappe.db.get_value('Address', dl[0][0], ['address_line1','address_line2','city','state','country','pincode'], as_dict=1) or {} %}
  {% endif %}
{% endif %}
{% set cust_addr_doc = {} %}
{% if doc.customer %}
  {% set cdl = frappe.db.sql("SELECT parent FROM `tabDynamic Link` WHERE link_doctype='Customer' AND link_name=%s AND parenttype='Address' LIMIT 1", doc.customer) %}
  {% if cdl %}
    {% set cust_addr_doc = frappe.db.get_value('Address', cdl[0][0], ['address_line1','address_line2','city','state','country','pincode'], as_dict=1) or {} %}
  {% endif %}
{% endif %}
{% set current_user_name = frappe.db.get_value('User', frappe.session.user, 'full_name') or frappe.session.user %}
{% macro v(x) %}{{ x if x else '-' }}{% endmacro %}
{% macro fd(d) %}{% if d %}{{ frappe.format(d, {'fieldtype':'Date'}) }}{% else %}-{% endif %}{% endmacro %}
{% macro fc(n) %}{% if n %}{{ frappe.format(n, {'fieldtype':'Currency'}) }}{% else %}0.00{% endif %}{% endmacro %}

<style>
/* ─────────────────────────────────────────────────────────────
   80mm THERMAL RECEIPT LAYOUT

   Thermal printheads are one-bit devices: they can burn a dot or
   leave it blank, with no grey in between. Anything that isn't
   pure black gets dithered into a speckle pattern, which is why
   the previous revision printed as unreadable smudged bands —
   it used solid #0580a3 fills behind WHITE text for the header,
   table head, totals bar and footer. Dithering that fill leaves
   roughly half the dots burnt, and the white glyphs sitting on
   top have nothing left to contrast against.

   Rules this layout follows, and that any future edit must keep:
     1. Ink is #000 on bare white. No reverse (light-on-dark) text.
     2. No background fills, no grey text, no hairline grey rules.
        Emphasis comes from BORDERS, WEIGHT and SIZE instead.
     3. Nothing below 9px. A 203dpi head resolves ~8 dots/mm, so
        smaller glyph strokes drop out entirely between dots.
     4. No webfont. The old Google Fonts @import silently failed
        on the server-side PDF renderer (no outbound network), so
        the real metrics were never what was designed against.
   ───────────────────────────────────────────────────────────── */

@page{
  size:80mm 297mm;
  margin:0mm;
}

/* wkhtmltopdf (the "Get PDF" button) ignores @page entirely — it reads
   page-size/page-width/page-height/margin-* only when declared as literal
   properties on the .print-format selector itself (see frappe.utils.pdf.
   get_print_format_styles), so that rule has to be duplicated here in a
   form wkhtmltopdf's scraper understands. */
.print-format{
  page-size:Custom;
  page-width:80mm;
  page-height:297mm;
  margin-top:4mm;
  margin-bottom:4mm;
  margin-left:4mm;
  margin-right:4mm;
}

*{box-sizing:border-box;margin:0;padding:0;}
html,body{
  width:100%;
  max-width:100%;
}
/* .print-format deliberately has NO explicit width here: it already carries
   margin-left/right (above, for wkhtmltopdf's page-margin scraper) and a
   block element's default width:auto correctly subtracts its own margin
   from the available space. Forcing width:100% here as well was the actual
   bug behind the right-edge clipping seen in testing — width:100% does NOT
   subtract margin the way width:auto does, so the box extended margin-right
   past the container's edge and got clipped there. */
body,.print-format{
  font-family:Arial,'Helvetica Neue',Helvetica,sans-serif;
  font-size:11px;
  font-weight:400;
  color:#000;
  background:#fff;
  line-height:1.35;
  overflow-x:hidden;
  -webkit-font-smoothing:none;
}

/* ── HEADER ── */
.hdr{
  padding:0 0 8px;
  text-align:center;
  margin:0 4px 14px;
  border-bottom:2px solid #000;
}
/* The company mark is a full-colour gradient PNG. Dithered at receipt
   size it prints as a dark blob, so it is capped small and paired with
   the company name set as real text, which is what actually has to be
   readable. */
.co-logo-img{
  max-height:30px;
  max-width:34mm;
  object-fit:contain;
  margin-bottom:4px;
  display:inline-block;
}
.co-title{
  font-size:15px;
  font-weight:700;
  color:#000;
  line-height:1.2;
  text-transform:uppercase;
}
.co-subtitle{
  font-size:10px;
  color:#000;
  text-transform:uppercase;
  letter-spacing:0.5px;
  margin-top:2px;
  font-weight:600;
}
.co-tax{
  font-size:10px;
  color:#000;
  margin-top:2px;
  font-weight:600;
}

.doc-title-wrap{
  margin:0 4px 12px;
  padding:6px 0;
  border-top:2px solid #000;
  border-bottom:2px solid #000;
  text-align:center;
}
.doc-title{
  font-size:20px;
  font-weight:700;
  color:#000;
  letter-spacing:2px;
  line-height:1.1;
}

.meta-box{margin:0 4px 16px;}
.meta-line{
  display:flex;
  justify-content:space-between;
  font-size:11px;
  padding:2px 0;
}
.meta-k{color:#000;font-weight:600;text-transform:uppercase;}
.meta-v{color:#000;font-weight:700;text-align:right;}

/* ── INFO ROW ── */
.info-row{margin:0 4px 16px;}
.info-col{width:100%;}
.sec-label{
  font-size:10px;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:1px;
  color:#000;
  margin-bottom:6px;
  border-top:1px solid #000;
  border-bottom:1px solid #000;
  padding:3px 0;
}
.cust-name{
  font-size:13px;
  font-weight:700;
  color:#000;
  margin-bottom:2px;
}
.cust-sub{font-size:11px;color:#000;margin-bottom:3px;font-weight:600;}
.cust-addr-box{
  font-size:10.5px;
  color:#000;
  margin-bottom:4px;
  line-height:1.35;
}
.ct-row{display:flex;gap:4px;margin-bottom:1px;font-size:10.5px;color:#000;}
.ct-k{font-weight:700;color:#000;min-width:52px;text-transform:uppercase;}

/* ── ITEM TABLE ──
   Header emphasis is border-driven: heavy rule above, thin rule below,
   black uppercase bold type in between. No fill, no reverse text. */
.pf-table{
  width:calc(100% - 8px);
  table-layout:fixed;
  border-collapse:collapse;
  font-size:11px;
  margin:0 4px 14px;
  page-break-inside:auto;
}
.pf-table th,
.pf-table td{
  overflow-wrap:break-word;
  word-break:break-word;
}
.pf-table thead{display:table-header-group;}
.pf-table tbody{display:table-row-group;}
.pf-table tr{
  page-break-inside:avoid;
  page-break-after:auto;
}
.pf-table thead tr{
  border-top:2px solid #000;
  border-bottom:1px solid #000;
}
.pf-table thead th{
  padding:4px 3px;
  color:#000;
  font-size:10px;
  font-weight:700;
  text-transform:uppercase;
  text-align:left;
  white-space:nowrap;
}
.pf-table thead th.r{text-align:right;}
.pf-table thead th.c,
.pf-table tbody td.c{padding-left:2px;padding-right:2px;}
.pf-table thead th.c{text-align:center;}
.pf-table tbody tr{border-bottom:1px dashed #000;}
.pf-table tbody td{padding:5px 3px;color:#000;vertical-align:top;font-weight:400;}
.pf-table tbody td.r{text-align:right;}
.pf-table tbody td.c{text-align:center;}
.desc-main{font-weight:600;color:#000;}
.total-val{font-weight:700;color:#000;}

/* ── TOTALS ── */
.totals-wrap{margin:0 4px 18px;page-break-inside:avoid;}
.tot-card{width:100%;}
.tot-line{
  display:flex;
  justify-content:space-between;
  padding:3px 0;
  font-size:11px;
}
.tot-k{color:#000;font-weight:600;}
.tot-v{color:#000;font-weight:700;text-align:right;}
/* Was a filled colour bar with white text; now the same visual weight is
   carried by a boxed double rule and a larger, heavier face. */
.tot-line.grand{
  border-top:2px solid #000;
  border-bottom:2px solid #000;
  padding:5px 0;
  margin:2px 0;
}
.tot-line.grand .tot-k{font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:1px;}
.tot-line.grand .tot-v{font-size:15px;font-weight:700;}
.tot-line.due{
  border-top:1px solid #000;
  border-bottom:2px solid #000;
  padding:4px 0;
}
.tot-line.due .tot-k{font-size:12px;font-weight:700;text-transform:uppercase;}
.tot-line.due .tot-v{font-size:13px;font-weight:700;}
.amt-words{
  width:100%;
  margin-top:5px;
  padding-top:4px;
  border-top:1px dashed #000;
  font-size:10px;
  color:#000;
  line-height:1.35;
  text-align:left;
  font-weight:600;
}

/* ── NOTES ── */
{% if doc.notes %}
.notes-wrap{margin:0 4px 18px;page-break-inside:avoid;}
.notes-txt{font-size:10.5px;color:#000;line-height:1.4;font-weight:400;}
{% endif %}

/* ── SIGNATURE ── */
.sig-row{
  display:flex;
  flex-direction:column;
  align-items:stretch;
  margin:0 4px 20px;
  gap:24px;
  page-break-inside:avoid;
}
.thank-card{
  border-top:1px dashed #000;
  border-bottom:1px dashed #000;
  padding:8px 4px;
  text-align:center;
}
.thank-title{
  font-size:12px;
  font-weight:700;
  color:#000;
  text-transform:uppercase;
  letter-spacing:0.5px;
}
.thank-sub{
  font-size:10px;
  color:#000;
  margin-top:3px;
  line-height:1.35;
}
.sig-container{display:flex;justify-content:center;}
.sig-box{text-align:center;width:100%;}
.sig-space{height:26px;}
.sig-line-bar{
  width:100%;
  border-top:2px solid #000;
  margin-bottom:4px;
}
.sig-name{
  font-size:11px;
  font-weight:700;
  color:#000;
  text-transform:uppercase;
}
.sig-role{
  font-size:10px;
  color:#000;
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:0.5px;
  margin-top:1px;
}

/* ── FOOTER ── */
.pf-footer{
  border-top:2px solid #000;
  color:#000;
  padding:8px 0 0;
  text-align:center;
  margin:12px 4px 0;
  font-size:10px;
  page-break-inside:avoid;
}
.foot-left-block{line-height:1.4;}
.foot-user-title{font-weight:700;color:#000;font-size:10.5px;}
.foot-date-text{font-size:10px;color:#000;}
.foot-right-block{
  text-align:center;
  line-height:1.4;
  margin-top:5px;
  padding-top:5px;
  border-top:1px dashed #000;
  width:100%;
}
.foot-co-name{font-weight:700;color:#000;font-size:11.5px;text-transform:uppercase;}

.keep{page-break-inside:avoid;}
@media print{
  /* 80mm receipt rolls print one continuous strip with no fixed "page
     bottom" to pin against, so unlike the old A4 layout the footer stays
     in normal document flow here — right after the signature block —
     instead of being position:fixed to the bottom of a page box. */
  body,.print-format{color:#000;}
}
</style>

<!-- HEADER -->
<div class="hdr">
  {% if co_logo %}
  <div><img src="{{ co_logo }}" alt="{{ co_name }}" class="co-logo-img" /></div>
  {% endif %}
  <div class="co-title">{{ co_name }}</div>
  <div class="co-subtitle">Job Management System</div>
  {% if co_tax %}<div class="co-tax">VAT Reg: {{ co_tax }}</div>{% endif %}
</div>

<div class="doc-title-wrap">
  <div class="doc-title">JOB ORDER</div>
</div>

<div class="meta-box">
  <div class="meta-line"><span class="meta-k">Job No</span><span class="meta-v">{{ v(doc.name) }}</span></div>
  <div class="meta-line"><span class="meta-k">Date</span><span class="meta-v">{{ fd(doc.date) }}</span></div>
</div>

<!-- INFO ROW -->
<div class="info-row keep">
  <div class="info-col">
    <div class="sec-label">Job To</div>
    <div class="cust-name">{{ v(doc.customer_name or doc.customer) }}</div>
    {% if doc.job_title %}<div class="cust-sub">{{ doc.job_title }}</div>{% endif %}

    {% if cust_addr_doc.get('address_line1') %}
    <div class="cust-addr-box">
      <div>{{ cust_addr_doc.address_line1 }}</div>
      {% if cust_addr_doc.get('address_line2') %}<div>{{ cust_addr_doc.address_line2 }}</div>{% endif %}
      <div>
        {% if cust_addr_doc.get('city') %}{{ cust_addr_doc.city }}{% endif %}
        {% if cust_addr_doc.get('state') %}, {{ cust_addr_doc.state }}{% endif %}
        {% if cust_addr_doc.get('country') %} - {{ cust_addr_doc.country }}{% endif %}
      </div>
    </div>
    {% endif %}

    {% if doc.customer_mobile %}<div class="ct-row"><span class="ct-k">Phone:</span><span>{{ doc.customer_mobile }}</span></div>{% endif %}
    {% if doc.vat_no %}<div class="ct-row"><span class="ct-k">VAT No:</span><span>{{ doc.vat_no }}</span></div>{% endif %}
    {% if doc.iqama_no %}<div class="ct-row"><span class="ct-k">IQAMA:</span><span>{{ doc.iqama_no }}</span></div>{% endif %}
  </div>
</div>

<!-- TABLE WITH REPEATING HEADER & NATURAL PAGE BREAKS -->
{% if doc.items %}
{% set ns = namespace(qty=0, amt=0) %}
{% for item in doc.items %}
  {% set ns.qty = ns.qty + (item.job_qty or 1) %}
  {% set ns.amt = ns.amt + (item.total or 0) %}
{% endfor %}
<table class="pf-table">
  <thead>
    <tr>
      <th class="c" style="width:10%">No</th>
      <th style="width:44%">Description</th>
      <th class="c" style="width:13%">Qty</th>
      <th class="r" style="width:33%">Total</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="c">01</td>
      <td>
        <div class="desc-main">Miscellaneous work</div>
      </td>
      <td class="c">{{ ns.qty }}</td>
      <td class="r total-val">{{ fc(ns.amt) }}</td>
    </tr>
  </tbody>
</table>

<!-- TOTALS -->
{% set fin = doc.get_financials() or {} %}
{% set total_received = (fin.get('received_from_customer') or 0.0) + (fin.get('received_from_agent') or 0.0) %}
{# Balance Due is the plain reconciliation of this job's own Total against
   what's actually been received for it — Total minus Paid, whichever way it
   goes, so Total / Paid / Balance Due always add up on the printed receipt.
   An overpaid job (Paid > Total) shows the excess as a Balance Due amount
   too rather than silently reading 0. #}
{% set balance_due = ((doc.net_amount or 0.0) - total_received) | abs %}
<div class="totals-wrap">
  <div class="tot-card">
    {% if doc.gross_amount %}
    <div class="tot-line"><span class="tot-k">Subtotal</span><span class="tot-v">{{ fc(doc.gross_amount) }}</span></div>
    {% endif %}
    {% if doc.discount %}
    <div class="tot-line"><span class="tot-k">Discount</span><span class="tot-v">- {{ fc(doc.discount) }}</span></div>
    {% endif %}
    <div class="tot-line grand"><span class="tot-k">Total</span><span class="tot-v">{{ fc(doc.net_amount) }}</span></div>
    {% if total_received > 0 %}
    <div class="tot-line"><span class="tot-k">Paid / Advance</span><span class="tot-v">- {{ fc(total_received) }}</span></div>
    <div class="tot-line due"><span class="tot-k">Balance Due</span><span class="tot-v">{{ fc(balance_due) }}</span></div>
    {% endif %}
  </div>
  {% if doc.net_amount %}
  <div class="amt-words">Amount in Words: {{ frappe.utils.money_in_words(doc.net_amount, co_currency) }}</div>
  {% endif %}
</div>
{% endif %}

<!-- NOTES -->
{% if doc.notes %}
<div class="notes-wrap keep">
  <div class="sec-label">Notes &amp; Remarks</div>
  <div class="notes-txt">{{ doc.notes | striptags }}</div>
</div>
{% endif %}

<!-- SIGNATURE ROW -->
<div class="sig-row keep">
  <div class="thank-card">
    <div class="thank-title">Thank you for your business!</div>
    <div class="thank-sub">We appreciate your partnership and look forward to working with you again.</div>
  </div>
  <div class="sig-container">
    <div class="sig-box">
      <div class="sig-space"></div>
      <div class="sig-line-bar"></div>
      <div class="sig-name">{{ co_name }}</div>
      <div class="sig-role">Authorized Signatory</div>
    </div>
  </div>
</div>

<!-- FOOTER -->
<div class="pf-footer keep">
  <div class="foot-left-block">
    <div>Printed / Prepared By: <span class="foot-user-title">{{ current_user_name }}</span></div>
    <div class="foot-date-text">{{ frappe.format(frappe.utils.now(), {'fieldtype':'Datetime'}) }}</div>
  </div>

  <div class="foot-right-block">
    <div class="foot-co-name">{{ co_name }}</div>
    {% if addr_doc.get('address_line1') %}<div>{{ addr_doc.address_line1 }}</div>{% endif %}
    {% if addr_doc.get('address_line2') %}<div>{{ addr_doc.address_line2 }}</div>{% endif %}
    <div>
      {% if addr_doc.get('city') %}{{ addr_doc.city }}{% endif %}
      {% if addr_doc.get('state') %}, {{ addr_doc.state }}{% endif %}
      {% if addr_doc.get('country') %} - {{ addr_doc.country }}{% endif %}
    </div>
    {% if co_phone or co_email %}
    <div style="margin-top:2px;">
      {% if co_phone %}<span>Ph: {{ co_phone }}</span>{% endif %}
      {% if co_phone and co_email %} | {% endif %}
      {% if co_email %}<span>{{ co_email }}</span>{% endif %}
    </div>
    {% endif %}
  </div>
</div>
